def eddy_cuda9_1_execute(params: EddyCuda91, runner: Runner | None = None) -> EddyCuda91Outputs:
    """
    eddy_cuda9.1

    A tool for correcting eddy currents and movements in diffusion data

    Author: FMRIB Analysis Group, University of Oxford

    URL: https://fsl.fmrib.ox.ac.uk/fsl/fslwiki

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    eddy_cuda9_1_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(EDDY_CUDA9_1_METADATA)
    execution.params(params)
    args = eddy_cuda9_1_cargs(params, execution)
    out = eddy_cuda9_1_outputs(params, execution)
    execution.run(args)
    return out

def eddy_cuda9_1(
    imain: InputPathType,
    mask: InputPathType,
    index: InputPathType,
    acqp: InputPathType,
    bvecs: InputPathType,
    bvals: InputPathType,
    out: str = "eddy_corrected",
    mb: float | None = None,
    mb_offs: float | None = None,
    slspec: InputPathType | None = None,
    json: InputPathType | None = None,
    mporder: float | None = None,
    s2v_lambda: float | None = None,
    topup: InputPathType | None = None,
    field: InputPathType | None = None,
    field_mat: InputPathType | None = None,
    flm: EddyCuda91Flm | None = None,
    slm: EddyCuda91Slm | None = None,
    fwhm: float | None = None,
    niter: float | None = None,
    s2v_niter: float | None = None,
    cnr_maps: bool = False,
    residuals: bool = False,
    fep: bool = False,
    interp: EddyCuda91Interp | None = None,
    s2v_interp: EddyCuda91Interp | None = None,
    resamp: EddyCuda91Resamp | None = None,
    nvoxhp: float | None = None,
    initrand: float | None = None,
    ff: float | None = None,
    repol: bool = False,
    ol_nstd: float | None = None,
    ol_nvox: float | None = None,
    ol_type: EddyCuda91OlType | None = None,
    ol_pos: bool = False,
    ol_sqr: bool = False,
    estimate_move_by_susceptibility: bool = False,
    mbs_niter: float | None = None,
    mbs_lambda: float | None = None,
    mbs_ksp: float | None = None,
    dont_sep_offs_move: bool = False,
    dont_peas: bool = False,
    data_is_shelled: bool = False,
    verbose: bool = False,
    runner: Runner | None = None,
) -> EddyCuda91Outputs:
    """
    eddy_cuda9.1

    A tool for correcting eddy currents and movements in diffusion data

    Author: FMRIB Analysis Group, University of Oxford

    URL: https://fsl.fmrib.ox.ac.uk/fsl/fslwiki

    Args:
        imain: File containing all the images to estimate distortions for
        mask: Mask to indicate brain
        index: File containing indices for all volumes in --imain into --acqp and\
            --topup
        acqp: File containing acquisition parameters
        bvecs: File containing the b-vectors for all volumes in --imain
        bvals: File containing the b-values for all volumes in --imain
        out: Basename for output
        mb: Multi-band factor
        mb_offs: Multi-band offset (-1 if bottom slice removed, 1 if top slice\
            removed)
        slspec: Name of text file completely specifying slice/group acuistion. N.B.\
            --slspec and --json are mutually exclusive.
        json: Name of .json text file with information about slice timing. N.B.\
            --json and --slspec are mutually exclusive.
        mporder: Order of slice-to-vol movement model (default 0, i.e. vol-to-vol
        s2v_lambda: Regularisation weight for slice-to-vol movement. (default 1,\
            reasonable range 1--10)
        topup: Base name for output files from topup
        field: Name of file with susceptibility field (in Hz)
        field_mat: Name of rigid body transform for susceptibility field
        flm: First level EC model (movement/linear/quadratic/cubic, default\
            quadratic)
        slm: Second level EC model (none/linear/quadratic, default none)
        fwhm: FWHM for conditioning filter when estimating the parameters (default\
            0)
        niter: Number of iterations (default 5)
        s2v_niter: Number of iterations for slice-to-vol (default 5)
        cnr_maps: Write shell-wise cnr-maps (default false)
        residuals: Write residuals (between GP and observations), (default false)
        fep: Fill empty planes in x- or y-directions (default false)
        interp: Interpolation model for estimation step (spline/trilinear, default\
            spline)
        s2v_interp: Slice-to-vol interpolation model for estimation step\
            (spline/trilinear, default trilinear)
        resamp: Final resampling method (jac/lsr, default jac)
        nvoxhp: # of voxels used to estimate the hyperparameters (default 1000)
        initrand: Seeds rand for when selecting voxels (default 0=no seeding)
        ff: Fudge factor for hyperparameter error variance (default 10.0)
        repol: Detect and replace outlier slices (default false))
        ol_nstd: Number of std off to qualify as outlier (default 4)
        ol_nvox: Min # of voxels in a slice for inclusion in outlier detection\
            (default 250)
        ol_type: Type of outliers, slicewise (sw), groupwise (gw) or both (both).\
            (default sw)
        ol_pos: Consider both positive and negative outliers if set (default false)
        ol_sqr: Consider outliers among sums-of-squared differences if set (default\
            false)
        estimate_move_by_susceptibility: Estimate how susceptibility field changes\
            with subject movement (default false)
        mbs_niter: Number of iterations for MBS estimation (default 10)
        mbs_lambda: Weighting of regularisation for MBS estimation (default 10)
        mbs_ksp: Knot-spacing for MBS field estimation (default 10mm)
        dont_sep_offs_move: Do NOT attempt to separate field offset from subject\
            movement (default false)
        dont_peas: Do NOT perform a post-eddy alignment of shells (default false)
        data_is_shelled: Assume, don't check, that data is shelled (default false)
        verbose: switch on diagnostic messages
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = eddy_cuda9_1_params(
        imain=imain,
        mask=mask,
        index=index,
        acqp=acqp,
        bvecs=bvecs,
        bvals=bvals,
        out=out,
        mb=mb,
        mb_offs=mb_offs,
        slspec=slspec,
        json=json,
        mporder=mporder,
        s2v_lambda=s2v_lambda,
        topup=topup,
        field=field,
        field_mat=field_mat,
        flm=flm,
        slm=slm,
        fwhm=fwhm,
        niter=niter,
        s2v_niter=s2v_niter,
        cnr_maps=cnr_maps,
        residuals=residuals,
        fep=fep,
        interp=interp,
        s2v_interp=s2v_interp,
        resamp=resamp,
        nvoxhp=nvoxhp,
        initrand=initrand,
        ff=ff,
        repol=repol,
        ol_nstd=ol_nstd,
        ol_nvox=ol_nvox,
        ol_type=ol_type,
        ol_pos=ol_pos,
        ol_sqr=ol_sqr,
        estimate_move_by_susceptibility=estimate_move_by_susceptibility,
        mbs_niter=mbs_niter,
        mbs_lambda=mbs_lambda,
        mbs_ksp=mbs_ksp,
        dont_sep_offs_move=dont_sep_offs_move,
        dont_peas=dont_peas,
        data_is_shelled=data_is_shelled,
        verbose=verbose,
    )
    return eddy_cuda9_1_execute(params, runner)

